import{d as r,C as s,o as d,c as h,a3 as t,E as e,j as a,a as g}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十七章","description":"《正易心法》第二十七章——每卦之体，六画便具：初爻为地、上爻为天、二北五南、四西三东，天地四方是为六虚；六画乃天地四方之象，非六虚即六画。","frontmatter":{"title":"正易心法·第二十七章","description":"《正易心法》第二十七章——每卦之体，六画便具：初爻为地、上爻为天、二北五南、四西三东，天地四方是为六虚；六画乃天地四方之象，非六虚即六画。","category":"guide","aliases":["正易心法第二十七章","每卦之体六画便具","六虚"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-27.md","filePath":"yijing/zheng-yi-xin-fa/chapter-27.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-27.md"},x=r({...c,setup(u){const i=[{id:"z27-01",label:"一、六画便具六虚",showLabel:!0,sentences:[["每卦之体，",{text:"六画",glossary:"liuhua"},"便具。天地四方，是为",{text:"六虚",glossary:"liuxu"},"。"]],note:["每一个卦的本体，六爻便已完整具备；天、地、东、南、西、北四方，就是六虚。（**「六虚」的「虚」是空间，不是实体**：六爻不是六个实体，而是六个空间方位的象征。**这一章把卦从「符号」变成了「坐标」**——每一卦都是一个完整的宇宙空间模型。）"]},{id:"z27-02",label:"二、六爻方位",showLabel:!0,sentences:[["初爻为地，上爻为天，二爻为北，五爻为南，四爻为西，三爻为东。天地四方，每卦之体，皆具此义，是为六虚。"]],note:["初爻对应地，上爻对应天，二爻对应北，五爻对应南，四爻对应西，三爻对应东。天地四方，每一个卦的本体都具备这个意义，这就是六虚。（**对应不是随意排的**：初在最下为地、上在最上为天（纵轴）；**中爻二、五是上下卦的「中位」，主南北**；三、四爻在下卦之顶、上卦之底，正是阴阳交界处，主东西。**天地（上下）+ 南北 + 东西 = 一个完整的三维坐标。**）"]},{id:"z27-03",label:"三、周流六虚",showLabel:!0,sentences:[["《大传》：“变动不拘，",{text:"周流六虚",glossary:"zhouliuLiuxu"},"”正谓此耳。"]],note:["《大传》（《系辞传》）说「变动不拘，周流六虚」，说的正是这个。（**两种读法**：传统理解把六虚当作「卦内的六个格子」，爻在格子里移动；麻衣的读法是「六虚＝天地四方」，爻的变动遍及整个宇宙空间。**前者封闭在符号内部，后者让卦与宇宙直接对应。** 通行本作「变动不居」，此处「不拘」随底本。）"]},{id:"z27-04",label:"四、六画之象",showLabel:!0,sentences:[["学者不悟，谓六虚天地四方，乃六画也，殊不知六画乃天地四方之象。"]],note:["学者不能领悟，以为六虚、天地四方就是六爻的画线而已——却不知道，六爻的画线正是天地四方的象征。（**这一句把「象」与「实」的关系点破了**：六画是「象」（看得见的符号），六虚是「实」（看不见的空间）。**在易学里，「虚」反而是「实」，「实」（符号）反而是「虚」（表象）。** 这与全书一贯的认识论一致：不要停留在符号层面，要穿透符号看见它所指向的真实。）"]},{id:"z27-05",label:"五、纸上工夫",showLabel:!0,sentences:[["此之谓",{text:"纸上工夫",glossary:"zhishangGongfu"},"，不知",{text:"落处",glossary:"luochu"},"也。"]],note:["这就叫做纸上工夫，不知道落处。（**这是全书第一次用「落处」来批评一种具体的错误**：把六画当成六虚，就是把地图当成了土地。**「纸上工夫」四字与第一章「玩占亦虚语」完全同调**——麻衣对「只做书面功夫」的批评，从他开篇一直贯到此处。）"]}],l=[{id:"liuhua",term:"六画",pinyin:"liù huà",meaning:"六爻卦的六条爻画。麻衣强调六画只是「象」，不是「实」。"},{id:"liuxu",term:"六虚",pinyin:"liù xū",meaning:"六个虚位。虚＝空间：六爻对应天地四方六个空间维度。"},{id:"zhouliuLiuxu",term:"周流六虚",pinyin:"zhōu liú liù xū",meaning:"《系辞传》语。麻衣读作「爻的变动遍及天地四方」，而非「在卦内六个格子里移动」。"},{id:"zhishangGongfu",term:"纸上工夫",pinyin:"zhǐ shàng gōng fu",meaning:"只在文字与符号层面下功夫。麻衣批评语：只知符号，不知实义。"},{id:"luochu",term:"落处",pinyin:"luò chù",meaning:"卦象的实际落脚之处。全书核心词，本章第一次用它来批评具体错误。"}];return(b,n)=>{const p=s("DaoTextReading"),o=s("DaoKeywordCards");return d(),h("div",null,[n[0]||(n[0]=t("",21)),e(p,{colophon:"六画便具 · 天地四方 · 周流六虚 · 知落处",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十七章原文",sections:i,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文引《大传》作「变动不拘」，通行本作「变动不居」，此处随底本，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[g("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(o,{items:[{term:"六虚",pinyin:["liù","xū"],meaning:"六个虚位。「虚」是空间而非实体：六爻对应天地四方六个空间维度，故「虚」反而是「实」。"},{term:"六爻方位",pinyin:["liù","yáo"],meaning:"初爻为地、上爻为天、二爻为北、五爻为南、四爻为西、三爻为东——一个完整的三维坐标。"},{term:"周流六虚",pinyin:["zhōu","liú"],meaning:"《系辞》语。麻衣读作「爻的变动遍及天地四方」，而非「在卦内六个格子里移动」。"},{term:"六画之象",pinyin:["liù","huà"],meaning:"六画是「象」（看得见的符号），六虚是「实」（看不见的空间）——不可把象当实。"},{term:"纸上工夫",pinyin:["zhǐ","shàng"],meaning:"只在符号层面下功夫，即把地图当土地。与第一章「玩占亦虚语」同调。"}]}),n[3]||(n[3]=t("",25))])}}});export{y as __pageData,x as default};
